/* Minimal Supabase bundle shim for Pages — provides the small client surface used by index.html
   It uses Supabase REST endpoints and the provided key. This is intentionally small and safe for client-side use.
*/
(function(){
  if (window.supabase && window.supabase.createClient) return;
  window.supabase = window.supabase || {};
  window.supabase.createClient = function(baseUrl, apiKey){
    const headers = {'Content-Type':'application/json','apikey':apiKey,'Authorization':'Bearer '+apiKey};
    function tableClient(table){
      return {
        upsert: async function(payload){
          try{
            const res = await fetch(baseUrl + '/rest/v1/' + table, {
              method: 'POST',
              headers: Object.assign({'Prefer':'resolution=merge-duplicates'}, headers),
              body: JSON.stringify(payload)
            });
            if(!res.ok){
              const t = await res.text();
              return { error: { message: t, status: res.status } };
            }
            const d = await res.json();
            return { data: d, error: null };
          }catch(e){ return { error: { message: String(e) } }; }
        },
        select: function(){
          return { eq: function(col,val){ return { single: async function(){
            try{
              const q = `${baseUrl}/rest/v1/${table}?${encodeURIComponent(col)}=eq.${encodeURIComponent(val)}`;
              const res = await fetch(q, { method: 'GET', headers });
              if(!res.ok){ const t = await res.text(); return { data: null, error: { message: t, status: res.status } }; }
              const json = await res.json();
              return { data: (json&&json.length)?json[0]:null, error: null };
            }catch(e){ return { data: null, error: { message: String(e) } }; }
          } } } }
        }
      };
    }
    return { from: tableClient };
  };
})();
